import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";

export type AppContext = {};

// Helper: parse cookies from a Cookie header string into a Map
function parseCookies(cookieHeader: string | null): Map<string, string> {
  const map = new Map<string, string>();
  if (!cookieHeader) return map;
  for (const part of cookieHeader.split(";")) {
    const idx = part.indexOf("=");
    if (idx === -1) continue;
    map.set(part.slice(0, idx).trim(), part.slice(idx + 1).trim());
  }
  return map;
}

// KV key under which the ordered list of messages is stored as JSON
const MESSAGES_KEY = "messages";

export default defineApp([
  setCommonHeaders(),

  // GET / — render form with fresh CSRF token + set cookie
  route("/", async ({ request, env }) => {
    if (request.method !== "GET") {
      return new Response("Method Not Allowed", { status: 405 });
    }

    const token = crypto.randomUUID();

    // Dynamically import the Home page component so we can pass the token
    const { HomePage } = await import("@/app/pages/home");

    // Render the full HTML document server-side
    const { renderToReadableStream } = await import("react-dom/server.edge");
    const React = (await import("react")).default;

    const stream = await renderToReadableStream(
      React.createElement(Document, null,
        React.createElement(HomePage, { csrfToken: token })
      )
    );

    return new Response(stream, {
      status: 200,
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        // Double-submit cookie: HttpOnly=false so the form can read it if needed,
        // SameSite=Strict for defence-in-depth, Path=/ so it is sent on POST /submit
        "Set-Cookie": `csrf_token=${token}; Path=/; SameSite=Strict`,
      },
    });
  }),

  // POST /submit — CSRF validation then persist message
  route("/submit", async ({ request, env }) => {
    if (request.method !== "POST") {
      return new Response("Method Not Allowed", { status: 405 });
    }

    // Parse form body
    let formData: FormData;
    try {
      formData = await request.formData();
    } catch {
      return new Response("Bad Request", { status: 400 });
    }

    const formToken = formData.get("csrf_token");
    const message = formData.get("message");

    // Parse cookie header
    const cookies = parseCookies(request.headers.get("cookie"));
    const cookieToken = cookies.get("csrf_token");

    // Double-submit-cookie validation
    if (
      !formToken ||
      !cookieToken ||
      typeof formToken !== "string" ||
      formToken !== cookieToken
    ) {
      return new Response("Forbidden", { status: 403 });
    }

    // Persist message
    const messageStr = typeof message === "string" ? message : "";
    const existing = await (env as Env).MESSAGES_KV.get(MESSAGES_KEY);
    const messages: string[] = existing ? JSON.parse(existing) : [];
    messages.push(messageStr);
    await (env as Env).MESSAGES_KV.put(MESSAGES_KEY, JSON.stringify(messages));

    return new Response("OK", { status: 200 });
  }),

  // GET /messages — return persisted messages as JSON array
  route("/messages", async ({ request, env }) => {
    if (request.method !== "GET") {
      return new Response("Method Not Allowed", { status: 405 });
    }

    const existing = await (env as Env).MESSAGES_KV.get(MESSAGES_KEY);
    const messages: string[] = existing ? JSON.parse(existing) : [];

    return new Response(JSON.stringify(messages), {
      status: 200,
      headers: {
        "Content-Type": "application/json",
      },
    });
  }),
]);

interface HomePageProps {
  csrfToken: string;
}

export const HomePage = ({ csrfToken }: HomePageProps) => {
  return (
    <main style={{ fontFamily: "sans-serif", maxWidth: "600px", margin: "2rem auto", padding: "0 1rem" }}>
      <h1>Message Board</h1>

      <section>
        <h2>Post a Message</h2>
        <form method="POST" action="/submit">
          <input type="hidden" name="csrf_token" value={csrfToken} />
          <div style={{ marginBottom: "0.75rem" }}>
            <label htmlFor="message" style={{ display: "block", marginBottom: "0.25rem" }}>
              Message
            </label>
            <textarea
              id="message"
              name="message"
              rows={4}
              style={{ width: "100%", boxSizing: "border-box" }}
              required
            />
          </div>
          <button type="submit">Send</button>
        </form>
      </section>

      <section style={{ marginTop: "2rem" }}>
        <h2>All Messages</h2>
        <p>
          View all persisted messages at{" "}
          <a href="/messages">/messages</a>.
        </p>
      </section>
    </main>
  );
};

// Keep a default export alias so any existing imports don't break
export const Home = () => <HomePage csrfToken="" />;

